CREATE TABLE IF NOT EXISTS environment_preparation_operations (request_id TEXT PRIMARY KEY, preparation_session_id TEXT NOT NULL, state TEXT NOT NULL, failure_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (preparation_session_id) REFERENCES preparation_sessions(id));
CREATE TABLE IF NOT EXISTS environment_preparation_candidates (id TEXT PRIMARY KEY, preparation_session_id TEXT NOT NULL, environment_conditions TEXT NOT NULL, safe_summary TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (preparation_session_id) REFERENCES preparation_sessions(id));
CREATE TABLE IF NOT EXISTS environment_preparation_diagnostics (id TEXT PRIMARY KEY, preparation_session_id TEXT NOT NULL, code TEXT NOT NULL, safe_summary TEXT NOT NULL, occurred_at TEXT NOT NULL, FOREIGN KEY (preparation_session_id) REFERENCES preparation_sessions(id));
